(() => {
 const grade=document.querySelector('#quiz-grade'),language=document.querySelector('#quiz-language'),subject=document.querySelector('#quiz-subject'),stage=document.querySelector('#quiz-stage');
 const strings={en:{question:'Question',of:'of',check:'Check answer',next:'Next question',finish:'See results',correct:'Correct.',incorrect:'Not quite.',choose:'Choose an answer first.',answer:'The correct answer is',score:'Quiz complete',retry:'Try again',restart:'Start a new quiz',reading:'Read or listen to the story',notice:'This is practice, not a formal school assessment.',work:'What is'},nso:{question:'Potšišo',of:'go tše',check:'Lekola karabo',next:'Potšišo ye e latelago',finish:'Bona dipoelo',correct:'Go lokile.',incorrect:'Ga se yona.',choose:'Kgetha karabo pele.',answer:'Karabo ya maleba ke',score:'O feditše dipotšišo',retry:'Leka gape',restart:'Thoma dipotšišo tše mpsha',reading:'Bala goba o theeletše kanegelo',notice:'Ye ke teko ya go itlwaetša, e sego tekolo ya semmušo ya sekolo.',work:'Ke bokae'}};
 let questions=[],story=null,index=0,score=0,locked=false;
 const make=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;};
 function shuffle(a){for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
 function start(){const lang=language.value,s=strings[lang];index=0;score=0;locked=false;story=null;if(subject.value==='maths'){questions=schoolQuizData.maths[grade.value].map(q=>{const values=[q.value,Math.round((q.value+1)*100)/100,Math.round((q.value-1)*100)/100,Math.round((q.value+2)*100)/100];const choices=shuffle(values.filter((v,i,a)=>a.indexOf(v)===i&&(grade.value!=='R'||v>=0))).map(String);return {question:`${s.work} ${q.expression}?`,options:choices,correct:choices.indexOf(String(q.value)),explanation:`${q.expression} = ${q.value}. ${q.explanation[lang]}`};});}else{const reading=schoolQuizData.reading.find(r=>r.grades.includes(grade.value));story=reading.story[lang];questions=reading.questions.map(q=>{const options=shuffle(q.options[lang].map((text,i)=>({text,right:i===q.correct})));return {question:q.question[lang],options:options.map(x=>x.text),correct:options.findIndex(x=>x.right),explanation:q.explanation[lang]};});}render();}
 function render(){const s=strings[language.value],q=questions[index];locked=false;stage.replaceChildren();stage.lang=language.value;const progress=make('p',`${s.question} ${index+1} ${s.of} ${questions.length}`,'eyebrow');stage.append(progress);if(story){const storyBox=make('div',undefined,'quiz-story');storyBox.append(make('h3',s.reading),make('p',story));stage.append(storyBox);}const form=make('form'),field=make('fieldset');field.append(make('legend',q.question));q.options.forEach((choice,i)=>{const label=make('label',undefined,'quiz-option'),input=document.createElement('input');input.type='radio';input.name='quiz-choice';input.value=String(i);label.append(input,document.createTextNode(' '+choice));field.append(label);});const check=make('button',s.check,'button primary');check.type='submit';const feedback=make('p');feedback.setAttribute('role','status');const next=make('button',index===questions.length-1?s.finish:s.next,'button outline');next.type='button';next.disabled=true;form.append(field,check,feedback,next);stage.append(form);form.addEventListener('submit',event=>{event.preventDefault();if(locked)return;const chosen=form.querySelector('input:checked');if(!chosen){feedback.textContent=s.choose;return;}locked=true;const right=Number(chosen.value)===q.correct;if(right)score++;feedback.textContent=`${right?s.correct:s.incorrect} ${s.answer}: ${q.options[q.correct]}. ${q.explanation}`;field.disabled=true;check.disabled=true;next.disabled=false;});next.addEventListener('click',()=>{if(!locked)return;index++;if(index<questions.length)render();else results();});}
 function results(){const s=strings[language.value];stage.replaceChildren();const heading=make('h3',s.score);heading.tabIndex=-1;stage.append(heading,make('p',`${score} / ${questions.length}`,'quiz-result'),make('p',s.notice));const retry=make('button',s.retry,'button primary');retry.type='button';retry.addEventListener('click',start);stage.append(retry);heading.focus();}
 [grade,language,subject].forEach(x=>x.addEventListener('change',start));start();
})();
